  @SneakyThrows
  public static void main(String[] args) {
//    var analyzer = new StandardAnalyzer();
//    var analyzer = new StopAnalyzer();
//    Analyzer analyzer = new StandardAnalyzer();
    var analyzer = CustomAnalyzer.builder()
      .withTokenizer("standard")
      .build();

    analyze(SAMPLE_TEXT, analyzer).forEach(System.out::println);

  }

  private static void analyzeWithCoreNlp() {
    Properties props = new Properties();
    props.setProperty("annotators", "tokenize");
    StanfordCoreNLP pipeline = new StanfordCoreNLP(props);

    var document = new CoreDocument(SAMPLE_TEXT);
    pipeline.annotate(document);
    for (CoreLabel tok : document.tokens()) {

      System.out.println(tok.word());
//      tok.word(), null, tok.beginPosition(), tok.endPosition())
    }
  }

  public static List<String> analyze(String text, Analyzer analyzer) throws IOException {
    List<String> result = new ArrayList<>();
    TokenStream tokenStream = analyzer.tokenStream("FIELD", text);
    CharTermAttribute attr = tokenStream.addAttribute(CharTermAttribute.class);
    tokenStream.reset();
    while (tokenStream.incrementToken()) {
      result.add(attr.toString());
    }
    return result;
  }

